-- Errata reading for H06: Age = latest reported age (most recent demographic_updates age_reported received by the as-of date, else the roster age_reported); everything else as the reference.
WITH copd AS MATERIALIZED ( SELECT DISTINCT patient FROM records WHERE stream='conditions' AND ( substr(json_extract(payload,'$.icd10'),1,3)='J44' OR json_extract(payload,'$.snomed') IN ('185086009','87433001')) ) SELECT COUNT(*) AS count FROM copd c JOIN patients p ON p.id=c.patient WHERE json_type(p.payload,'$.age_reported')='integer' AND coalesce((SELECT json_extract(du_.payload,'$.age_reported') FROM records du_ WHERE du_.stream='demographic_updates' AND du_.patient=p.id AND json_extract(du_.payload,'$.age_reported') IS NOT NULL ORDER BY json_extract(du_.payload,'$.age_reference_date') DESC LIMIT 1), json_extract(p.payload,'$.age_reported'))>=65;
